    },
    {
      "element_id": "prisma_2020_12_e2",
      "status": "PRESENT",
      "chunk_id": "text_22",
      "quote": "To evaluate certainty of no benefit (or no effect), we used a 2% risk difference threshold of the 95% credible interval for mortality and mechanical ventilation. We decided on this preliminary threshold based on a survey of the authors.",
