    },
    {
      "element_id": "prisma_2020_12_e3",
      "status": "PRESENT",
      "chunk_id": "text_23",
      "quote": "To facilitate interpretation of the results, we calculated absolute effects for outcomes in which the summary measure was an odds ratio or ratio of means.",
      "reason": "Describes methods to re-express synthesized results (from odds ratio or ratio of means to absolute effects)."
    },
    {
      "element_id": "prisma_2020_12_e4",
      "status": "PRESENT",
      "chunk_id": "text_19",
      "quote": "For continuous outcomes, we used the mean difference and corresponding 95% credible interval in days for ICU length of stay, length of hospital stay, and duration of mechanical ventilation because we expected similar durations across randomised trials. For time to symptom resolution, we first performed the analyses using the relative effect measure ratio of means and corresponding 95% credible interval before calculating the mean difference in days because we expected substantial variation between studies.",
      "reason": "Justifies choice of effect measure (mean difference for similar durations, ratio of means for variation) for specific outcomes."
    }
  ],
